    function RunDiagnosticsPanel({ runId, projectId, requestId, errorMessage }) {
        const [diagnostics, setDiagnostics] = useState(null);
        const [loadError, setLoadError] = useState(null);
        const [loading, setLoading] = useState(false);
        useEffect(()=>{
            if (!runId) {
                setDiagnostics(null);
                return;
            }
            let cancelled = false;
            setLoading(true);
            setLoadError(null);
            void (async ()=>{
                try {
                    const params = new URLSearchParams({
                        project_id: projectId
                    });
                    const response = await fetch(`/api/runtime/runs/${encodeURIComponent(runId)}/diagnostics?${params.toString()}`);
                    const body = await response.json();
                    if (!response.ok) {
                        throw new Error(body.error ?? "Failed to load diagnostics");
                    }
                    if (!cancelled) {
                        setDiagnostics(body);
                    }
                } catch (error) {
                    if (!cancelled) {
                        setLoadError(error instanceof Error ? error.message : "Failed to load diagnostics");
                    }
                } finally{
                    if (!cancelled) {
                        setLoading(false);
                    }
                }
            })();
            return ()=>{
                cancelled = true;
            };
        }, [
            runId,
            projectId
        ]);
        if (!runId && !requestId && !errorMessage) {
            return null;
        }
        return jsxs("div", {
            className: "mt-2 rounded-md border border-red-200 bg-red-50 px-3 py-2 text-xs text-red-900",
            "data-testid": "run-diagnostics-panel",
            role: "alert",
            children: [
                jsx("p", {
                    className: "font-medium",
                    children: "Runtime dispatch failed"
                }),
                errorMessage ? jsx("p", {
                    className: "mt-1 whitespace-pre-wrap",
                    children: errorMessage
                }) : null,
                requestId ? jsxs("p", {
                    className: "mt-1 font-mono text-[11px]",
                    children: [
                        "request_id: ",
                        requestId
                    ]
                }) : null,
                runId ? jsxs("p", {
                    className: "font-mono text-[11px]",
                    children: [
                        "run_id: ",
                        runId
                    ]
                }) : null,
                loading ? jsx("p", {
                    className: "mt-2 text-red-700",
                    children: "Loading diagnostics…"
                }) : null,
                loadError ? jsx("p", {
                    className: "mt-2 text-red-700",
                    children: loadError
                }) : null,
                diagnostics?.last_error ? jsxs("div", {
                    className: "mt-2 space-y-1 font-mono text-[11px]",
                    children: [
                        diagnostics.last_error.phase ? jsxs("p", {
                            children: [
                                "phase: ",
                                diagnostics.last_error.phase
                            ]
                        }) : null,
                        diagnostics.last_error.message ? jsxs("p", {
                            children: [
                                "detail: ",
                                diagnostics.last_error.message
                            ]
                        }) : null
                    ]
                }) : null,
                diagnostics && diagnostics.dispatch_events.length > 0 ? jsxs("details", {
                    className: "mt-2",
                    children: [
                        jsxs("summary", {
                            className: "cursor-pointer text-red-800",
                            children: [
                                "Dispatch trace (",
                                diagnostics.dispatch_events.length,
                                ")"
                            ]
                        }),
                        jsx("ul", {
                            className: "mt-1 max-h-40 space-y-1 overflow-y-auto font-mono text-[10px]",
                            children: diagnostics.dispatch_events.map((entry)=>jsxs("li", {
                                    children: [
                                        entry.ts,
                                        " ",
                                        entry.event,
                                        entry.phase ? ` [${entry.phase}]` : "",
                                        entry.error_message ? ` — ${entry.error_message}` : ""
                                    ]
                                }, `${entry.ts}-${entry.event}`))
                        })
                    ]
                }) : null
            ]
        });
    }
