    function reconnectMessage(failureReason, expectedSubdomain) {
        if (failureReason === "subdomain_malformed") {
            if (expectedSubdomain) {
                return `Composio stored an invalid subdomain. Reconnect and enter only "${expectedSubdomain}" — not the full .atlassian.net URL.`;
            }
            return "Composio stored an invalid subdomain. Reconnect and enter only the site slug before .atlassian.net.";
        }
        if (failureReason === "credential_invalid") {
            return "OAuth completed, but the token lacks required Confluence scopes (401). Disconnect, revoke the Composio app at id.atlassian.com → Authorized apps, then reconnect in a private window.";
        }
        if (failureReason === "remote_inactive") {
            return "Composio connection is incomplete or refreshing. Reconnect to finish authorization.";
        }
        return "Connection stored locally but Composio cannot use it — disconnect and connect again.";
    }
    function IntegrationConnectionActions({ slotId, provider, projectId = "default", compact = false, verified = true, needsReconnect = false, failureReason = null, expectedSubdomain = null, onStateChange }) {
        const [disconnecting, setDisconnecting] = useState(false);
        const [error, setError] = useState(null);
        async function handleDisconnect() {
            setDisconnecting(true);
            setError(null);
            try {
                const params = new URLSearchParams({
                    project_id: projectId
                });
                if (provider) {
                    params.set("provider", provider);
                }
                const response = await fetch(`/api/integrations/${encodeURIComponent(slotId)}/disconnect?${params.toString()}`, {
                    method: "POST",
                    headers: {
                        "Content-Type": "application/json"
                    },
                    body: "{}"
                });
                const payload = await response.json();
                if (!response.ok) {
                    throw new Error(payload.error ?? "Disconnect failed");
                }
                onStateChange?.();
            } catch (disconnectError) {
                const message = disconnectError instanceof Error ? disconnectError.message : "Disconnect failed";
                setError(message);
            } finally{
                setDisconnecting(false);
            }
        }
        const buttonClassName = compact ? "rounded border border-gray-300 bg-white px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-gray-700 hover:bg-gray-50 disabled:opacity-50" : "rounded-md border border-gray-300 bg-white px-3 py-1.5 text-sm font-medium text-gray-700 hover:bg-gray-50 disabled:opacity-50";
        return jsxs("div", {
            "data-testid": `integration-connection-actions-${slotId}`,
            className: compact ? "flex shrink-0 flex-col items-end gap-2" : "mb-3",
            children: [
                needsReconnect ? jsx("p", {
                    className: `text-xs text-amber-700 ${compact ? "max-w-[240px] text-right" : "mb-2"}`,
                    role: "status",
                    children: reconnectMessage(failureReason, expectedSubdomain)
                }) : null,
                !verified && !needsReconnect ? jsx("p", {
                    className: `text-xs text-amber-700 ${compact ? "max-w-[200px] text-right" : "mb-2"}`,
                    children: "Verifying connection with Composio…"
                }) : null,
                jsxs("div", {
                    className: `flex flex-wrap gap-2 ${compact ? "justify-end" : ""}`,
                    children: [
                        needsReconnect ? jsx(IntegrationConnectButton, {
                            slotId,
                            provider,
                            label: "Reconnect",
                            compact,
                            onConnected: onStateChange
                        }) : null,
                        jsx("button", {
                            type: "button",
                            className: buttonClassName,
                            disabled: disconnecting,
                            onClick: ()=>{
                                void handleDisconnect();
                            },
                            children: disconnecting ? "…" : "Disconnect"
                        })
                    ]
                }),
                error ? jsx("p", {
                    className: `text-xs text-red-600 ${compact ? "mt-1 max-w-[200px] text-right" : "mt-1"}`,
                    role: "alert",
                    children: error
                }) : null
            ]
        });
    }
