    function swatchesToTokenSpecimens(swatches) {
        if (!swatches || swatches.length === 0) {
            return [];
        }
        return swatches.map((value, index)=>({
                name: `--swatch-${index + 1}`,
                value,
                type: "color",
                layer: "palette"
            }));
    }
    function parseDesignTokensPayload(text) {
        try {
            const payload = JSON.parse(text);
            if (!Array.isArray(payload.tokens)) {
                return [];
            }
            return payload.tokens.filter((token)=>{
                return typeof token.name === "string" && typeof token.value === "string";
            }).map((token)=>({
                    name: token.name,
                    value: token.value,
                    type: token.type,
                    layer: token.layer,
                    confidence: token.confidence
                }));
        } catch  {
            return [];
        }
    }
    async function fetchDesignSystemTokenSpecimens(designSystemId) {
        const tokensText = await designFetchText(`/design-systems/${encodeURIComponent(designSystemId)}/static?path=${encodeURIComponent("design-tokens.json")}`);
        if (tokensText) {
            const parsed = parseDesignTokensPayload(tokensText);
            if (parsed.length > 0) {
                return parsed;
            }
        }
        const cssText = await designFetchText(`/design-systems/${encodeURIComponent(designSystemId)}/static?path=${encodeURIComponent("tokens.css")}`);
        if (!cssText) {
            return [];
        }
        const specimens = [];
        const tokenPattern = /(--[\w-]+)\s*:\s*([^;]+);/g;
        let match = tokenPattern.exec(cssText);
        while(match){
            specimens.push({
                name: match[1],
                value: match[2].trim(),
                type: "css-variable"
            });
            match = tokenPattern.exec(cssText);
        }
        return specimens;
    }
    async function getDesignSystem(designSystemId) {
        try {
            const payload = await designFetch(`/design-systems/${encodeURIComponent(designSystemId)}`);
            const detail = payload.designSystem ?? payload;
            if (!detail.id) {
                return null;
            }
            const tokenFile = await fetchDesignSystemTokenSpecimens(designSystemId);
            const swatchTokens = swatchesToTokenSpecimens(detail.swatches);
            const tokens = tokenFile.length > 0 ? tokenFile : swatchTokens;
            return {
                ...detail,
                tokens
            };
        } catch  {
            return null;
        }
    }
