    async function* readPluginInstallEvents(body) {
        const reader = body.getReader();
        const decoder = new TextDecoder();
        let buffer = "";
        while(true){
            const { value, done } = await reader.read();
            if (done) {
                break;
            }
            buffer += decoder.decode(value, {
                stream: true
            });
            let frameIndex = buffer.indexOf("\n\n");
            while(frameIndex !== -1){
                const frame = buffer.slice(0, frameIndex);
                buffer = buffer.slice(frameIndex + 2);
                const dataLine = frame.split("\n").find((line)=>line.startsWith("data:"));
                if (dataLine) {
                    try {
                        yield JSON.parse(dataLine.slice(5).trim());
                    } catch  {}
                }
                frameIndex = buffer.indexOf("\n\n");
            }
        }
    }
    async function installPluginFromSource(source) {
        const response = await fetch(`${DESIGN_API_PREFIX}/plugins/install`, {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
                Accept: "text/event-stream"
            },
            body: JSON.stringify({
                source
            })
        });
        if (!response.ok) {
            const text = await response.text().catch(()=>"");
            return {
                ok: false,
                message: text || `Install failed (${response.status})`
            };
        }
        if (!response.body) {
            return {
                ok: false,
                message: "Install stream did not start"
            };
        }
        let successMessage = "Plugin installed";
        let pluginId;
        let pluginTitle;
        let errorMessage;
        for await (const event of readPluginInstallEvents(response.body)){
            if (event.kind === "success" && event.plugin) {
                pluginId = event.plugin.id;
                pluginTitle = event.plugin.title;
                successMessage = event.message ?? `Installed ${pluginTitle ?? "plugin"}`;
            }
            if (event.kind === "error") {
                errorMessage = event.message ?? "Install failed";
            }
        }
        if (errorMessage) {
            return {
                ok: false,
                message: errorMessage
            };
        }
        return {
            ok: Boolean(pluginId),
            message: successMessage,
            pluginId,
            pluginTitle
        };
    }
