    const FULL_CLASS = "h-6 w-auto max-w-[120px] object-contain object-left";
    const DEFAULT_ASSETS = {
        icon: {
            src: "/brand/icon-light.png",
            width: 36,
            height: 36
        },
        full: {
            src: "/brand/wordmark-light.png",
            width: void 0,
            height: 24
        }
    };
    function resolveAssetSrc(variant, assets) {
        if (variant === "icon") {
            return {
                src: assets?.icon_light ?? DEFAULT_ASSETS.icon.src,
                width: DEFAULT_ASSETS.icon.width,
                height: DEFAULT_ASSETS.icon.height
            };
        }
        return {
            src: assets?.wordmark_light ?? DEFAULT_ASSETS.full.src,
            width: DEFAULT_ASSETS.full.width,
            height: DEFAULT_ASSETS.full.height
        };
    }
    function BrandLogo({ variant = "full", className, title = "Control Plane", assets }) {
        const sizeClass = variant === "icon" ? ICON_CLASS : FULL_CLASS;
        const merged = className ? `${sizeClass} ${className}` : sizeClass;
        const asset = resolveAssetSrc(variant, assets);
        return jsx("img", {
            src: asset.src,
            alt: title,
            className: merged,
            width: asset.width,
            height: asset.height,
            decoding: "async",
            "data-testid": variant === "icon" ? "sidebar-rail-logo" : "brand-wordmark"
        });
    }
    function joinScratchDir(workspaceRoot) {
        const normalized = workspaceRoot.replace(/\\/g, "/").replace(/\/+$/, "");
        return `${normalized}/scratch`;
    }
    function buildOrchestratorProjectDefaults(context) {
        return {
            baseDir: joinScratchDir(context.workspaceRoot),
            orchestratorWorkspace: {
                kind: "scratch",
                sourceLabel: `harness:${context.harnessProjectId}`,
                writeback: "external"
            }
        };
    }
    async function fetchHarnessWorkspaceContext() {
        try {
            const response = await fetch("/api/projects");
            if (!response.ok) {
                return null;
            }
            const payload = await response.json();
            const projects = payload.projects ?? [];
            const active = projects.find((project)=>project.active) ?? projects.find((project)=>project.id === "default") ?? projects[0];
            if (!active?.id) {
                return null;
            }
            return {
                harnessProjectId: active.id,
                workspaceRoot: active.path?.trim() ?? ""
            };
        } catch  {
            return null;
        }
    }
    const CONVERSATION_STORAGE_PREFIX = "design-harness-conversation:";
    const DESIGN_PENDING_PROMPT_PREFIX = "design-pending-prompt:";
    function storeDesignPendingPrompt(projectId, prompt) {
        if (typeof window === "undefined") {
            return;
        }
        const trimmed = prompt.trim();
        if (!trimmed) {
            return;
        }
        sessionStorage.setItem(`${DESIGN_PENDING_PROMPT_PREFIX}${projectId}`, trimmed);
    }
    function consumeDesignPendingPrompt(projectId) {
        if (typeof window === "undefined") {
            return null;
        }
        const key = `${DESIGN_PENDING_PROMPT_PREFIX}${projectId}`;
        const value = sessionStorage.getItem(key);
        if (value?.trim()) {
            sessionStorage.removeItem(key);
            return value.trim();
        }
        return null;
    }
    function readStoredHarnessConversationId(projectId) {
        if (typeof window === "undefined") {
            return null;
        }
        const value = sessionStorage.getItem(`${CONVERSATION_STORAGE_PREFIX}${projectId}`);
        return value?.trim() ? value.trim() : null;
    }
    function storeHarnessConversationId(projectId, conversationId) {
        if (typeof window === "undefined") {
            return;
        }
        sessionStorage.setItem(`${CONVERSATION_STORAGE_PREFIX}${projectId}`, conversationId);
    }
    async function resolveOrCreateHarnessConversation(input) {
        const stored = input.existingConversationId?.trim() || readStoredHarnessConversationId(input.projectId);
        if (stored) {
            return stored;
        }
        const response = await fetch("/api/conversations", {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            body: JSON.stringify({
                title: input.projectName,
                project_id: input.harnessProjectId
            })
        });
        if (!response.ok) {
            throw new Error("Failed to create harness conversation for design project");
        }
        const payload = await response.json();
        const conversationId = payload.conversation?.id?.trim();
        if (!conversationId) {
            throw new Error("Conversation creation did not return an id");
        }
        storeHarnessConversationId(input.projectId, conversationId);
        return conversationId;
    }
